export async function GET(
  _req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const desk = await db.desk.findUnique({
    where: { id },
    include: { bookings: { orderBy: { start: 'desc' } } },
  })
